import bpy
import math

COLLECTION_NAME = "R6 Replay Cameras"
CAMERA_NAME = "R6Cam_dyn4mic_P01"
TRACK_NAME = "dyn4mic_P01"
TRACK_LABEL = "P01"
PLAYER_GUESS = "dyn4mic"
ACTOR_ID = "0100000000000000"
POSITION_PROP_ID = "000000005e1807f000000000"
ROTATION_PROP_ID = "000000005e1807f000000000"
ROTATION_MODE = "wrapped"
FPS = 60
FRAME_STEP = 1
LOCATION_SCALE = 1

def ensure_collection(name):
    collection = bpy.data.collections.get(name)
    if collection is None:
        collection = bpy.data.collections.new(name)
        bpy.context.scene.collection.children.link(collection)
    return collection

def remove_existing_object(name):
    obj = bpy.data.objects.get(name)
    if obj is not None:
        bpy.data.objects.remove(obj, do_unlink=True)

def keyframe_prop(obj, key, value, frame):
    obj[key] = value
    obj.keyframe_insert(data_path=f'["{key}"]', frame=frame)

collection = ensure_collection(COLLECTION_NAME)
remove_existing_object(CAMERA_NAME)
camera_data = bpy.data.cameras.new(CAMERA_NAME)
camera = bpy.data.objects.new(CAMERA_NAME, camera_data)
camera.rotation_mode = 'XYZ'
camera.data.clip_end = 10000
collection.objects.link(camera)
scene = bpy.context.scene
scene.camera = camera
scene.render.fps = FPS
camera['r6_track_name'] = TRACK_NAME
camera['r6_track_label'] = TRACK_LABEL
camera['r6_player_guess'] = PLAYER_GUESS
camera['r6_actor_id'] = ACTOR_ID
